<?php
declare(strict_types=1);ob_start();require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/super_app_v700.php';$u=v700_require_user();$uid=(int)$u['id'];$apps=v700_rows("SELECT a.*,i.name institution_name,p.title program_title FROM edu_applications_v700 a JOIN edu_institutions_v700 i ON i.id=a.institution_id LEFT JOIN edu_programs_v700 p ON p.id=a.program_id WHERE a.tenant_id=? AND a.user_id=? ORDER BY a.id DESC",[v700_tid(),$uid]);$enr=v700_rows("SELECT e.*,i.name institution_name,p.title program_title FROM edu_enrollments_v700 e JOIN edu_institutions_v700 i ON i.id=e.institution_id LEFT JOIN edu_programs_v700 p ON p.id=e.program_id WHERE e.tenant_id=? AND e.user_id=? ORDER BY e.id DESC",[v700_tid(),$uid]);$fees=v700_rows("SELECT f.*,e.roll_no,i.name institution_name FROM edu_fee_invoices_v700 f JOIN edu_enrollments_v700 e ON e.id=f.enrollment_id JOIN edu_institutions_v700 i ON i.id=e.institution_id WHERE f.tenant_id=? AND e.user_id=? ORDER BY f.id DESC",[v700_tid(),$uid]);v700_public_header('My Education','Applications, enrollment, attendance and fee tracking.','education');?>
<main><section class="v700-account-hero"><div class="v700-shell"><span class="v700-kicker">MY EDUCATION</span><h1><?=e($u['name']??'Student')?>'s education dashboard</h1><p>Track applications, active enrollments and fee invoices.</p></div></section><section class="v700-section soft"><div class="v700-shell"><div class="v700-account-grid"><a href="#apps"><b><?=count($apps)?></b><span>Applications</span></a><a href="#enroll"><b><?=count($enr)?></b><span>Enrollments</span></a><a href="#fees"><b><?=count($fees)?></b><span>Fee Invoices</span></a><a href="/education.php"><b>+</b><span>Find Institutions</span></a></div><section class="v700-panel" id="apps"><div class="v700-panel-head"><h2>Applications</h2></div><div class="v700-list"><?php foreach($apps as $a):?><div class="v700-row"><i>▤</i><span><b><?=e($a['institution_name'])?></b><small><?=e($a['program_title']?:'General admission')?> · <?=e($a['reference_no'])?></small></span><?=v700_status_badge($a['status'])?></div><?php endforeach;?><?php if(!$apps):?><div class="v700-empty">No applications yet.</div><?php endif;?></div></section><section class="v700-panel" id="enroll"><div class="v700-panel-head"><h2>Enrollments</h2></div><div class="v700-list"><?php foreach($enr as $e):?><div class="v700-row"><i>🎓</i><span><b><?=e($e['institution_name'])?></b><small><?=e($e['program_title']?:'Program')?> · Roll <?=e($e['roll_no']?:'Pending')?></small></span><?=v700_status_badge($e['status'])?></div><?php endforeach;?><?php if(!$enr):?><div class="v700-empty">No enrollments yet.</div><?php endif;?></div></section><section class="v700-panel" id="fees"><div class="v700-panel-head"><h2>Fee Invoices</h2></div><div class="v700-table-wrap"><table class="v700-table"><tr><th>Invoice</th><th>Institution</th><th>Amount</th><th>Paid</th><th>Due</th><th>Status</th></tr><?php foreach($fees as $f):?><tr><td><?=e($f['invoice_no'])?></td><td><?=e($f['institution_name'])?></td><td><?=v700_money((float)$f['amount'])?></td><td><?=v700_money((float)$f['paid_amount'])?></td><td><?=e($f['due_date']?:'—')?></td><td><?=v700_status_badge($f['status'])?></td></tr><?php endforeach;?></table></div></section></div></section></main><?php v700_public_footer(); ?>
